		public SiteTest setHandler(Handler handler) {
			this.handler = handler;
			LOGGER.addHandler(handler); // assign so the LOGGER can only output results to the Handler
			return this;
		}

		/**
		 * Returns a new populated Site
		 * 
		 * @return Site
		 */
		protected Site generateNewEntity() {
			Site entity = new Site( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  new Address(),  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  java.math.BigDecimal.ZERO,  java.math.BigDecimal.ZERO,  null,  new HashSet<>(),  new HashSet<>(),  new HashSet<>() );
			
			return( entity );
		}

